<template><AppShell title="申请售后" back footer><StateView :loading="loading" :error="error" :count="order?1:0" @retry="load" /><view v-if="order" class="pad"><view class="card row"><GameArt variant="mini" class="mini-cover" :game="order.game" /><view class="stack"><text class="bold">{{order.title}}</text><text class="muted tiny">{{order.orderNo}}</text><text class="price">¥{{money(order.amountCents)}}</text></view></view><view class="card"><view class="field-row"><text>售后类型</text><text>退款</text></view><view class="field-row"><text>申请原因</text><picker :range="reasons" @change="reason=reasons[$event.detail.value]"><view class="picker-value">{{reason}}<AppIcon class="app-icon" name="chevron" :size="14" /></view></picker></view><view class="field-row"><text>申请退款金额</text><text class="price">¥{{money(order.amountCents)}}</text></view><text class="muted tiny">平台将根据订单记录和双方说明处理申请</text></view><view class="card"><text class="field-label">问题描述</text><textarea v-model="description" @blur="description=$event.detail.value" class="textarea" maxlength="1000" placeholder="说明实际道具交付与约定的差异（至少 5 个字）" /><text class="note-count">{{description.length}}/1000</text><text class="field-label section">上传凭证（选填）</text><UploadImages purpose="AFTERSALE" v-model="evidence" @busy="uploading=$event" /></view><view class="notice"><AppIcon class="app-icon" name="shield" :size="26" /><view><text class="bold">平台协助处理</text><text class="muted tiny" style="display:block">提交后会暂停交付并通知对方，申请通过后办理退款。</text></view></view><text class="muted tiny" style="display:block;margin-top:15px">提交申请不会立即退款，请留意订单内的处理结果。</text><text v-if="formError" class="field-error">{{formError}}</text></view><template #footer><button class="ui-button btn wide" :disabled="busy||uploading||!order" @click="submit">{{busy?'正在提交…':'提交申请'}}</button></template></AppShell></template>
<script setup>
import {ref} from 'vue';import {onLoad,onShow} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import AppIcon from '../../components/AppIcon.vue';import GameArt from '../../components/GameArt.vue';import StateView from '../../components/StateView.vue';import UploadImages from '../../components/UploadImages.vue';import {request,money,toast,requireLogin,loadMe,loadConfig,session} from '../../lib/api';const id=ref(''),order=ref(null),loading=ref(false),error=ref(''),formError=ref(''),busy=ref(false),uploading=ref(false),description=ref(''),evidence=ref([]),reasons=['道具规格不符','未按约定交付','道具数量不符','协商退款'],reason=ref(reasons[0]);onLoad(q=>id.value=q.id);onShow(()=>{if(requireLogin())load()});async function load(){loading.value=true;error.value='';order.value=null;try{await Promise.all([loadMe(),loadConfig()]);if(session.config?.paymentsEnabled===false)throw new Error('支付及资金操作暂未开放');const o=await request('/boost/orders/'+id.value);if(o.buyerId!==session.user.id||o.aftersale||!['WAIT_START','IN_PROGRESS','REVIEW','WAIT_DELIVERY','WAIT_CONFIRM'].includes(o.status))throw new Error('当前订单不可再次申请售后，请返回订单详情查看');order.value=o}catch(e){error.value=e.message}finally{loading.value=false}}async function submit(){if(busy.value||uploading.value||!order.value)return;busy.value=true;formError.value='';try{await request(`/boost/orders/${id.value}/aftersale`,'POST',{reason:reason.value,description:description.value,images:evidence.value});toast('申请已提交');uni.redirectTo({url:'/pages/orders/detail?id='+id.value})}catch(e){formError.value=e.message}finally{busy.value=false}}
</script>

<style scoped>.card{padding:14px}.card .textarea{min-height:120px;background:#fff;padding:8px 0}.card .field-row{min-height:44px}.card .row{gap:10px}.notice{padding:14px}</style>
